        // =========================================================================
        // NETWORK LIVENESS & STRICT OFFLINE STATE CONTROLLER (v10.0)
        // Rule: Never serve stale/fake cached data when offline. Explicit alerts always.
        // =========================================================================
        window.updateNetworkLivenessUI = function(isOnline, customMsg = null) {
            const banner = document.getElementById('offlineNoticeBanner');
            const badge = document.getElementById('syncStatusText');
            const vSyncText = document.getElementById('visibleSyncText');
            const liveBadge = document.getElementById('liveUpdateBadge');
            const pulseDot = document.querySelector('.pulse-live');

            if (!isOnline) {
                if (banner) {
                    banner.classList.remove('hidden');
                    banner.style.display = 'block';
                }
                if (badge) badge.innerHTML = `<span class="inline-block w-2 h-2 rounded-full bg-rose-500 ml-1"></span>❌ غير متصل بالإنترنت (تعذر التحديث)`;
                if (vSyncText) vSyncText.textContent = 'منقطع';
                if (liveBadge) {
                    liveBadge.textContent = '❌ تعذر التحديث (غير متصل)';
                    liveBadge.style.color = '#f87171';
                }
                if (pulseDot) {
                    pulseDot.classList.remove('bg-emerald-400');
                    pulseDot.classList.add('bg-rose-500');
                }
            } else {
                if (banner) {
                    banner.classList.add('hidden');
                    banner.style.display = 'none';
                }
                if (vSyncText) vSyncText.textContent = 'حية';
                if (liveBadge) {
                    liveBadge.textContent = '⚡ أسعار حية';
                    liveBadge.style.color = '';
                }
                if (pulseDot) {
                    pulseDot.classList.remove('bg-rose-500');
                    pulseDot.classList.add('bg-emerald-400');
                }
            }
        };

        window.checkNetworkAndSync = async function(manual = false) {
            if (!navigator.onLine) {
                window.updateNetworkLivenessUI(false);
                if (manual && typeof showToast === 'function') {
                    showToast('⚠️ لا يوجد اتصال بالإنترنت حالياً — تعذر المزامنة. يرجى التحقق من الشبكة', 'error');
                }
                return false;
            }
            if (typeof window.refreshData === 'function') {
                return await window.refreshData();
            }
            return true;
        };

        window.addEventListener('online', () => {
            console.log('[Network] Connection restored');
            window.updateNetworkLivenessUI(true);
            if (typeof showToast === 'function') {
                showToast('✅ تم استعادة الاتصال بالإنترنت — جاري جلب أحدث الأسعار الحية...', 'success');
            }
            window.checkNetworkAndSync(false);
        });

        window.addEventListener('offline', () => {
            console.warn('[Network] Connection lost');
            window.updateNetworkLivenessUI(false);
            if (typeof showToast === 'function') {
                showToast('⚠️ انقطع الاتصال بالإنترنت — تعذر جلب التحديثات. تم إيقاف التحديث لمنع عرض بيانات قديمة', 'error');
            }
        });

        // Initialize network state check on load
        document.addEventListener('DOMContentLoaded', () => {
            if (!navigator.onLine) {
                window.updateNetworkLivenessUI(false);
            }
        });

        // =========================================================================

        // THEME MODE CONTROLLER (Dark / Light Mode)

        // =========================================================================

        function initThemeMode() {

            const savedTheme = localStorage.getItem('egx_theme_mode');

            const isDark = savedTheme ? (savedTheme === 'dark') : true;

            applyThemeMode(isDark, false);

        }



        function applyThemeMode(isDark, notify = false) {

            // Update visible theme toggle button

            const vIcon = document.getElementById('visibleThemeIcon');

            const vLabel = document.getElementById('visibleThemeLabel');

            if (vIcon) vIcon.textContent = isDark ? '🌙' : '☀️';

            if (vLabel) vLabel.textContent = isDark ? 'ليلي' : 'نهاري';

            if (isDark) {

                document.documentElement.classList.add('dark');

            } else {

                document.documentElement.classList.remove('dark');

            }



            // Update Meta Theme Color

            const metaThemeColor = document.getElementById('metaThemeColor') || document.querySelector('meta[name="theme-color"]');

            if (metaThemeColor) {

                metaThemeColor.setAttribute('content', isDark ? '#080c14' : '#f8fafc');

            }



            // Update Telegram WebApp Theme

            if (window.Telegram && window.Telegram.WebApp) {

                const tg = window.Telegram.WebApp;

                if (tg.setHeaderColor) tg.setHeaderColor(isDark ? '#080c14' : '#ffffff');

                if (tg.setBackgroundColor) tg.setBackgroundColor(isDark ? '#080c14' : '#f8fafc');

            }



            // Update Toggle Button UI

            const btn = document.getElementById('themeToggleBtn');

            const icon = document.getElementById('themeToggleIcon');

            const label = document.getElementById('themeToggleLabel');

            if (icon && label) {

                if (isDark) {

                    icon.innerText = '☀️';

                    label.innerText = 'نهاري';

                    if (btn) btn.title = 'التحويل إلى الوضع النهاري الفاتح (Light Mode)';

                } else {

                    icon.innerText = '🌙';

                    label.innerText = 'ليلي';

                    if (btn) btn.title = 'التحويل إلى الوضع الليلي المظلم (Dark Mode)';

                }

            }



            // Update Chart.js Doughnut Legend if active

            if (typeof donutChartInstance !== 'undefined' && donutChartInstance && donutChartInstance.options) {

                try {

                    donutChartInstance.options.plugins.legend.labels.color = isDark ? '#94a3b8' : '#334155';

                    donutChartInstance.update();

                } catch(e) {}

            }



            // Redraw Advanced Canvas Chart if open

            const chartModal = document.getElementById('stockChartModal');

            if (chartModal && !chartModal.classList.contains('hidden') && typeof drawAdvancedChart === 'function') {

                try {

                    drawAdvancedChart();

                } catch(e) {}

            }



            if (notify) {

                showToast(isDark ? 'تم التبديل إلى الوضع الليلي 🌙' : 'تم التبديل إلى الوضع النهاري ☀️', 'info');

            }

        }



        function toggleThemeMode() {

            triggerHaptic('selection');

            const isCurrentlyDark = document.documentElement.classList.contains('dark');

            const newDark = !isCurrentlyDark;

            localStorage.setItem('egx_theme_mode', newDark ? 'dark' : 'light');

            applyThemeMode(newDark, true);

        }



        // Force Cache Purge and Reload

        function forceAppUpdate() {

            triggerHaptic('medium');

            showToast('جاري تحديث المنصة وتفريغ الذاكرة المؤقتة بالكامل...', 'info');

            if ('caches' in window) {

                caches.keys().then(keys => Promise.all(keys.map(k => caches.delete(k))))

                .then(() => {

                    if ('serviceWorker' in navigator) {

                        navigator.serviceWorker.getRegistrations().then(regs => {

                            return Promise.all(regs.map(r => r.unregister()));

                        }).then(() => {

                            setTimeout(() => window.location.reload(true), 300);

                        });

                    } else {

                        setTimeout(() => window.location.reload(true), 300);

                    }

                });

            } else {

                window.location.reload(true);

            }

        }



