    function getMasterPin() {

        return localStorage.getItem('egx_security_pin') || DEFAULT_MASTER_PIN;

    }



    function isAppUnlocked() {

        return localStorage.getItem('egx_auth_unlocked') === 'true' || sessionStorage.getItem('egx_auth_unlocked') === 'true';

    }



    function initMasterSecurityLock() {

        // Platform starts unlocked by default for seamless mobile/desktop access

        // Users can lock the screen anytime using the lock button in the header/settings

        if (sessionStorage.getItem('egx_manual_locked') === 'true') {

            showSecurityLockScreen();

        } else {

            localStorage.setItem('egx_auth_unlocked', 'true');

            hideSecurityLockScreen();

        }



        // Global Keyboard Handler for PIN Entry

        window.addEventListener('keydown', (e) => {

            const screen = document.getElementById('masterSecurityLockScreen');

            if (!screen || screen.classList.contains('hidden')) return;



            if (e.key >= '0' && e.key <= '9') {

                enterPinDigit(e.key);

            } else if (e.key === 'Backspace') {

                backspacePinDigit();

            } else if (e.key === 'Enter') {

                validatePinSubmission();

            } else if (e.key === 'Escape') {

                clearPinInput();

            }

        });

    }



    function showSecurityLockScreen() {

        _pinBuffer = "";

        updatePinDisplayUI();

        const screen = document.getElementById('masterSecurityLockScreen');

        const main = document.querySelector('main');

        const header = document.querySelector('header');

        const nav = document.getElementById('bottomNav');



        if (screen) screen.classList.remove('hidden');

        if (main) main.classList.add('app-locked-blur');

        if (header) header.classList.add('app-locked-blur');

        if (nav) nav.classList.add('app-locked-blur');

        document.body.style.overflow = 'hidden';

        window.focus();

        setTimeout(() => {

            const card = document.getElementById('masterSecurityLockCard');

            if (card) { card.setAttribute('tabindex', '-1'); card.focus(); }

        }, 50);

    }



    function hideSecurityLockScreen() {

        const screen = document.getElementById('masterSecurityLockScreen');

        const main = document.querySelector('main');

        const header = document.querySelector('header');

        const nav = document.getElementById('bottomNav');



        if (screen) screen.classList.add('hidden');

        if (main) main.classList.remove('app-locked-blur');

        if (header) header.classList.remove('app-locked-blur');

        if (nav) nav.classList.remove('app-locked-blur');

        document.body.style.overflow = '';

    }





