                const changes = allStocks.map(s => typeof s.chg === 'number' ? s.chg : 0);

                const rsiVals = allStocks.map(s => typeof s.rsi === 'number' ? s.rsi : 50);

                const barColors = changes.map(c => c >= 0 ? 'rgba(52,211,153,0.85)' : 'rgba(248,113,113,0.85)');

                const rsiColors = rsiVals.map(r => r >= 70 ? 'rgba(248,113,113,0.9)' : r <= 35 ? 'rgba(52,211,153,0.9)' : 'rgba(56,189,248,0.85)');



                _renderDrCharts(codes, changes, rsiVals, barColors, rsiColors);



