                    const res = s.resistance || (typeof s.close === 'number' ? (s.close * 1.05).toFixed(2) + ' ج' : '—');

                    const action = s.rec || (s.chg >= 2 ? 'شراء وتجميع وزخم' : (s.chg <= -2 ? 'مراقبة واقتناص قاع' : 'احتفاظ ومراقبة'));

