            const cleanName = rawName.replace(/\s*\([A-Za-z0-9_]+\)/g, '').trim();

            const titleEl = document.getElementById('modalChartTitle');

            if (titleEl) titleEl.innerText = `${cleanName} (${data.ticker || ticker})`;

            const secEl = document.getElementById('modalStockSector');

            if (secEl) secEl.innerText = data.sector || 'سوق المال';

            const priceEl = document.getElementById('modalChartPrice');

