            const isFundAsset = ['AZG', 'THNDR_GOLD', 'CMS', 'BWA', 'NMF', 'USD_EGP'].includes(ticker) || (data.sector && (data.sector.includes('صندوق') || data.sector.includes('ذهب') || data.sector.includes('نقد') || data.sector.includes('دولار')));

            

