            // Percentages

            const fmtPct = (val) => (val >= 0 ? `+${val.toFixed(2)}%` : `${val.toFixed(2)}%`);

            const r2PctEl = document.getElementById('pivotModalR2Pct');

            const r1PctEl = document.getElementById('pivotModalR1Pct');

            const ppPctEl = document.getElementById('pivotModalPPPct');

