        // 5. Dynamic Dividends Table

        function renderDividendsTable(calendarData) {

            const tbody = document.getElementById('dividendsTableBody');

            if (!tbody) return;



            const data = calendarData || [

                { ticker: "ABUK", name: "أبو قير للأسمدة", coupon: 7.50, ex_date: "أكتوبر 2026", pay_date: "نوفمبر 2026", yield_pct: 8.4 },

                { ticker: "MFPC", name: "موبكو للأسمدة", coupon: 3.75, ex_date: "سبتمبر 2026", pay_date: "أكتوبر 2026", yield_pct: 8.1 },

                { ticker: "ORWE", name: "النساجون الشرقيون", coupon: 2.20, ex_date: "أكتوبر 2026", pay_date: "نوفمبر 2026", yield_pct: 7.9 },

                { ticker: "AMOC", name: "أموك للبترول", coupon: 1.10, ex_date: "نوفمبر 2026", pay_date: "ديسمبر 2026", yield_pct: 8.3 },

                { ticker: "SKPC", name: "سيدي كرير", coupon: 1.50, ex_date: "سبتمبر 2026", pay_date: "أكتوبر 2026", yield_pct: 8.2 }

            ];



            tbody.innerHTML = '';

            data.forEach(item => {

                const stock = STOCKS_DATA.find(s => s.ticker === item.ticker);

                const curPrice = stock ? stock.close : 0;

                const dynamicYield = curPrice > 0 ? ((item.coupon / curPrice) * 100) : item.yield_pct;



                const tr = document.createElement('tr');

                tr.className = "hover:bg-slate-800/40 transition cursor-pointer";

                tr.onclick = () => openStockChart(item.ticker);

                tr.innerHTML = `

                    <td class="py-2.5 font-bold text-white flex items-center gap-1.5">

                        <span class="font-mono text-emerald-400">${item.ticker}</span>

                        <span>${item.name}</span>

                    </td>

                    <td class="py-2.5 font-mono text-amber-300 font-bold">${item.coupon.toFixed(2)} ج</td>

                    <td class="py-2.5 font-mono text-emerald-400 font-bold">${dynamicYield.toFixed(1)}%</td>

                    <td class="py-2.5 text-slate-400 text-[10px]">${item.ex_date}</td>

                    <td class="py-2.5 text-slate-400 text-[10px]">${item.pay_date}</td>

                `;

                tbody.appendChild(tr);

            });

        }



        // 6. Subtab Switcher

        function switchMarketSubTab(sub) {

            triggerHaptic('selection');

            if (sub === 'news') {

                switchTab('news_hub');

                return;

            }

            if (sub === 'ai') {

                switchTab('recommendations');

                if (typeof switchRecAnalysisSlicer === 'function') switchRecAnalysisSlicer('analysis');

                return;

            }

            const views = {

                pulse: 'marketSubViewPulse',

                ai: 'marketSubViewAi',

                fair: 'marketSubViewFair'

            };

            const btns = {

                pulse: 'marketSubTabPulseBtn',

                ai: 'marketSubTabAiBtn',

                fair: 'marketSubTabFairBtn'

            };



            Object.keys(views).forEach(k => {

                const el = document.getElementById(views[k]);

                const b  = document.getElementById(btns[k]);

                if (!el || !b) return;

                if (k === sub) {

                    el.classList.remove('hidden');

                    b.className = "market-subtab-btn flex-1 py-2 rounded-xl font-bold bg-emerald-600 text-white shadow-sm transition active:scale-95 flex items-center justify-center gap-1";

                } else {

                    el.classList.add('hidden');

                    b.className = "market-subtab-btn flex-1 py-2 rounded-xl font-bold text-slate-400 hover:text-slate-200 transition active:scale-95 flex items-center justify-center gap-1";

                }

            });



            if (sub === 'fair') {

                if (typeof populateValuationStockSelect === 'function') populateValuationStockSelect(true);

                if (typeof renderValuationCard === 'function') renderValuationCard();

                if (typeof renderDividendsTable === 'function') renderDividendsTable();

            } else if (sub === 'pulse') {

                if (currentAssetSlicer === 'funds') {

                    if (typeof renderFundsCards === 'function') renderFundsCards();

                } else {

                    if (typeof renderStocks === 'function') renderStocks();

                    if (typeof updateMarketPulseLive === 'function') updateMarketPulseLive();

                }

            } else if (sub === 'news') {

                if (typeof renderNewsFeed === 'function') renderNewsFeed();

            } else if (sub === 'ai') {

                if (typeof updateAiMarketAdvisorView === 'function') updateAiMarketAdvisorView();

            }

        }



