        window.switchTab = switchTab;

        function switchTab(tabId, btn, pushHistory = true) {

            triggerHaptic('medium');

            

            // Backward compatibility routing

            let actualTabId = tabId;

            let subTarget = null;

            let isPerfRoute = false;



            if (tabId === 'performance') {

                actualTabId = 'portfolio';

                isPerfRoute = true;

            } else if (tabId === 'dca') {

                actualTabId = 'tools';

                subTarget = 'dca';

            } else if (tabId === 'zakat') {

                actualTabId = 'tools';

                subTarget = 'zakat';

            } else if (tabId === 'valuation') {

                actualTabId = 'radar';

                subTarget = 'fair';

            } else if (tabId === 'ai' || tabId === 'ai_chat') {

                actualTabId = 'recommendations';

                subTarget = 'analysis';

            }



            currentActiveTab = actualTabId;

            if (pushHistory) {

                pushAppState('tab', { tabId: actualTabId });

            }

            updateBackUI();



            // Hide all tab content

            document.querySelectorAll('.tab-content').forEach(el => el.classList.add('hidden'));



            // Mobile Bottom Nav Highlight

            document.querySelectorAll('.tab-btn').forEach(b => {

                b.className = "tab-btn flex flex-col items-center gap-0.5 py-1 px-0.5 rounded-2xl transition active:scale-90 text-slate-400";

                b.style.fontSize = "10px";

            });

            const activeMobileBtn = document.getElementById('tabBtn_' + actualTabId);

            if (activeMobileBtn) {

                activeMobileBtn.className = "tab-btn flex flex-col items-center gap-0.5 py-1 px-0.5 rounded-2xl transition active:scale-90 text-emerald-400 font-bold";

                activeMobileBtn.style.fontSize = "10px";

            }



            // Desktop Nav Highlight

            document.querySelectorAll('.desktop-tab-btn').forEach(b => {

                b.className = "desktop-tab-btn px-3 py-1.5 rounded-xl text-xs font-medium transition flex items-center gap-1.5 text-slate-300 hover:text-white hover:bg-slate-800/80";

            });

            const activeDesktopBtn = document.getElementById('desktopTab_' + actualTabId);

            if (activeDesktopBtn) {

                activeDesktopBtn.className = "desktop-tab-btn px-3 py-1.5 rounded-xl text-xs font-bold transition flex items-center gap-1.5 text-emerald-400 bg-emerald-950/80 border border-emerald-500/40 shadow-sm";

            }



            if (actualTabId === 'portfolio') {

                const portView = document.getElementById('view-portfolio');

                if (portView) portView.classList.remove('hidden');

                if (isPerfRoute) {

                    switchPortfolioSubTab('performance');

                } else {

                    switchPortfolioSubTab('holdings');

                }

            } else {

                const target = document.getElementById('view-' + actualTabId);

                if (target) target.classList.remove('hidden');



                if (actualTabId === 'radar') {

                    if (subTarget) switchMarketSubTab(subTarget);

                    else switchMarketSubTab('pulse');

                } else if (actualTabId === 'news_hub' || actualTabId === 'news') {

                    renderNewsHub('stocks');

                } else if (actualTabId === 'recommendations') {

                    if (subTarget === 'analysis') {

                        if (typeof switchRecAnalysisSlicer === 'function') switchRecAnalysisSlicer('analysis');

                    } else {

                        if (typeof switchRecAnalysisSlicer === 'function') switchRecAnalysisSlicer('recs');

                        else renderRecommendationsView();

                    }

                } else if (actualTabId === 'valuation') {

                    switchMarketSubTab('fair');

                } else if (actualTabId === 'tools') {

                    setTimeout(() => {

                        switchToolsSubTab(subTarget || 'audit');

                    }, 30);

                } else if (actualTabId === 'dailyreport') {

                    if (typeof initDailyReportTab === 'function') initDailyReportTab();

                }

            }



            window.scrollTo({ top: 0, behavior: 'smooth' });

        }



