        function setRecFilter(action, btn) {

            triggerHaptic('selection');

            recCurrentActionFilter = action;

            document.querySelectorAll('.rec-filter-btn').forEach(b => {

                b.className = "rec-filter-btn px-3 py-1.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-300 transition active:scale-95 flex items-center gap-1";

            });

            if (btn) {

                btn.className = "rec-filter-btn px-3 py-1.5 rounded-xl bg-amber-600 text-white font-bold transition active:scale-95 flex items-center gap-1";

            }

            renderRecommendationsView();

        }



        // setRecTypeFilter is defined above (unified implementation)



        // ════════════════════════════════════════════════════════

        //  v11 — SORT ENGINE & LIVE DATA CONNECTIONS

        // ════════════════════════════════════════════════════════



        // ── Sort State ──────────────────────────────────────────

        const _sortState = {

            stocks:    { col: null, dir: -1 },

            funds:     { col: null, dir: -1 },

            radar:     { col: 'chg', dir: -1 },

            dividends: { col: 'yield', dir: -1 }

        };



        // ── Update Sort Header Arrow Indicators ─────────────────

        function updateSortArrows(type, col, dir) {

            const prefix = type === 'stocks' ? 'sh_' : 'fh_';

            const cols = ['ticker', 'qty', 'buy', 'cur', 'val', 'pnl', 'pnlpct'];

            cols.forEach(c => {

                const elements = [

                    document.getElementById(prefix + c),

                    document.getElementById(prefix + 'smart_' + c)

                ].filter(Boolean);



                elements.forEach(th => {

                    const arrow = th.querySelector('.sort-arrow');

                    if (!arrow) return;

                    const isActive = (c === col);

                    if (isActive) {

                        arrow.textContent = dir > 0 ? ' ↑' : ' ↓';

                        arrow.classList.remove('opacity-40');

                        arrow.style.color = type === 'stocks' ? '#10b981' : '#f59e0b';

                        arrow.style.fontWeight = 'bold';

                        th.classList.add('text-slate-900', 'dark:text-white');

                    } else {

                        arrow.textContent = ' ↕';

                        arrow.classList.add('opacity-40');

                        arrow.style.color = '';

                        arrow.style.fontWeight = 'normal';

                        th.classList.remove('text-slate-900', 'dark:text-white');

                    }

                });

            });

        }



        // ── Sort Holdings Table (stocks or funds) ───────────────

        function sortHoldingsTable(type, col) {

            triggerHaptic('selection');

            const st = _sortState[type];

            if (!st) return;



            // Toggle direction if already active column, otherwise default to descending (-1)

            if (st.col === col) {

                st.dir *= -1;

            } else {

                st.col = col;

                st.dir = -1; // Default descending (من الأعلى للأدنى)

            }



            // Update arrow indicators

            updateSortArrows(type, st.col, st.dir);



            // Re-render table and cards with active sort order

            renderHoldingsTable();

        }



        // Expose globally for inline onclick handlers

        window.sortHoldingsTable = sortHoldingsTable;

        window.updateSortArrows = updateSortArrows;



        // Expose modern sort functions globally for inline onclick handlers

        window.sortRadar = typeof sortRadar === 'function' ? sortRadar : () => {};

        window.toggleRadarSortDir = typeof toggleRadarSortDir === 'function' ? toggleRadarSortDir : () => {};



        // ── Sort Dividends Table ─────────────────────────────────

        let _divSortCol = 'yield';

        let _divSortDir = -1;



        function sortDividendsTable(col) {

            if (_divSortCol === col) _divSortDir *= -1;

            else { _divSortCol = col; _divSortDir = -1; }

            const tbody = document.getElementById('dividendsTableBody');

            if (!tbody) return;

            const rows = Array.from(tbody.querySelectorAll('tr'));

            rows.sort((a, b) => {

                const cellMap = { name:0, coupon:1, yield:2 };

                const ci = cellMap[col] ?? 0;

                const va = a.cells[ci]?.textContent?.trim() || '';

                const vb = b.cells[ci]?.textContent?.trim() || '';

                const na = parseFloat(va.replace(/[^0-9.-]/g,''));

                const nb = parseFloat(vb.replace(/[^0-9.-]/g,''));

                if (!isNaN(na) && !isNaN(nb)) return (na - nb) * _divSortDir;

                return va.localeCompare(vb) * _divSortDir;

            });

            rows.forEach(r => tbody.appendChild(r));

        }



        // ════════════════════════════════════════════════════════

        //  LIVE DATA CONNECTIONS — Sync ALL sections after update

        // ════════════════════════════════════════════════════════



        async function syncAllLiveSections() {
            if (!navigator.onLine) {
                if (typeof window.updateNetworkLivenessUI === 'function') {
                    window.updateNetworkLivenessUI(false);
                }
                showToast('⚠️ لا يوجد اتصال بالإنترنت حالياً — تعذر المزامنة. تم إيقاف العملية تجنباً لعرض بيانات قديمة', 'error');
                return false;
            }

            // Flash badge
            const badge = document.getElementById('liveUpdateBadge');
            if (badge) { badge.textContent = '🔄 جارٍ التحديث...'; }

            let success = false;
            try {
                if (typeof syncLiveMarketData === 'function') {
                    const res = await syncLiveMarketData(false);
                    if (res !== false) success = true;
                }
            } catch(e) { console.warn('sync error:', e); }

            if (success) {
                // Update secondary sections
                updateLiveGoalsInput();
                updateLiveZakatInput();
                if (badge) {
                    badge.textContent = '🟢 محدث الآن';
                    badge.style.color = '#34d399';
                    setTimeout(() => {
                        badge.textContent = '⚡ أسعار حية';
                        badge.style.color = '';
                    }, 3500);
                }
                return true;
            } else {
                if (badge) {
                    badge.textContent = '❌ تعذر التحديث (غير متصل)';
                    badge.style.color = '#f87171';
                }
                return false;
            }
        }



        function updateLiveGoalsInput() {

            try {

                const totalVal = userHoldings.reduce((s,h) => s+(h.cur||h.buy||0)*h.qty, 0)

                              + (THNDR_CASH?.cash || 0);

                const el = document.getElementById('goal_current');

                if (el && !el.dataset.userModified) el.value = Math.round(totalVal);

            } catch(e) {}

        }



        function updateLiveZakatInput() {

            try {

                const stockVal = userHoldings.filter(h => !isFundAsset(h) && !isGoldAsset(h))

                    .reduce((s,h) => s+(h.cur||h.buy||0)*h.qty, 0);

                const el = document.getElementById('zakat_val');

                if (el && !el.dataset.userModified) el.value = Math.round(stockVal);

            } catch(e) {}

        }







        // Mark inputs as user-modified when touched

        document.addEventListener('DOMContentLoaded', () => {

            ['zakat_val','goal_current','goal_target','goal_monthly'].forEach(id => {

                const el = document.getElementById(id);

                if (el) el.addEventListener('input', () => el.dataset.userModified = '1');

            });



            // Initial live sync after 3s

            setTimeout(() => {

                try { updateLiveGoalsInput(); updateLiveZakatInput(); } catch(e) {}

            }, 3000);

        });



        // Override refreshData globally

        window.refreshData = syncAllLiveSections;





