        function renderUserActivityLog(filter = 'all') {

            const container = document.getElementById('userActivityFeedContainer');

            if (!container) return;

            container.innerHTML = '';



            const logs = getUserActivityLogs();



            // Compute counts

            const total = logs.length;

            const direct = logs.filter(l => l.type === 'adjust').length;

            const ocr = logs.filter(l => l.type === 'ocr').length;

            const trade = logs.filter(l => l.type === 'trade' || l.type === 'buy' || l.type === 'sell').length;



            const tEl = document.getElementById('actTotalCount');

            const dEl = document.getElementById('actDirectCount');

            const oEl = document.getElementById('actOcrCount');

            const rEl = document.getElementById('actTradeCount');

            if (tEl) tEl.innerText = `${total} حركة`;

            if (dEl) dEl.innerText = `${direct}`;

            if (oEl) oEl.innerText = `${ocr}`;

            if (rEl) rEl.innerText = `${trade}`;



            const filtered = logs.filter(l => {

                if (filter === 'all') return true;

                if (filter === 'ocr') return l.type === 'ocr';

                if (filter === 'adjust') return l.type === 'adjust';

                if (filter === 'trade') return l.type === 'trade' || l.type === 'buy' || l.type === 'sell';

                if (filter === 'sync') return l.type === 'sync' || l.type === 'reset';

                return true;

            });



            if (filtered.length === 0) {

                container.innerHTML = `

                    <div class="glass-card rounded-2xl p-6 text-center text-xs text-slate-400 space-y-1.5 border border-slate-800">

                        <div class="text-2xl">📋</div>

                        <h4 class="font-bold text-white text-sm">لا توجد حركات مسجلة في هذا التصنيف</h4>

                        <p class="text-[11px]">أي تعديل أو صفقة أو مسح صورة تقوم به سيظهر موثقاً هنا فوراً.</p>

                    </div>

                `;

                return;

            }



            filtered.forEach(log => {

                const card = document.createElement('div');

                card.className = "glass-card rounded-xl p-3 sm:p-3.5 border border-slate-800 space-y-2 hover:border-indigo-500/80 hover:bg-slate-900/60 transition select-none shadow-sm cursor-pointer group active:scale-[0.99]";

                card.onclick = () => openActivityDetailModal(log.id);

                

                let metaHtml = '';

                if (log.meta) {

                    const pills = [];

                    if (log.meta.oldQty !== undefined && log.meta.newQty !== undefined) {

                        pills.push(`الكمية: <b class="text-white">${log.meta.oldQty}</b> ← <b class="text-emerald-400">${log.meta.newQty}</b>`);

                    }

                    if (log.meta.oldBuy !== undefined && log.meta.newBuy !== undefined) {

                        pills.push(`سعر الشراء: <b class="text-white">${log.meta.oldBuy.toFixed(2)}</b> ← <b class="text-emerald-400">${log.meta.newBuy.toFixed(2)} ج</b>`);

                    }

                    if (log.meta.price !== undefined) {

                        pills.push(`سعر التنفيذ: <b class="text-white">${log.meta.price.toFixed(2)} ج</b>`);

                    }

                    if (log.meta.qty !== undefined && !log.meta.oldQty) {

                        pills.push(`الكمية: <b class="text-white">${log.meta.qty}</b>`);

                    }

                    if (log.meta.total !== undefined) {

                        pills.push(`إجمالي القيمة: <b class="text-emerald-400 font-bold">${typeof log.meta.total === 'number' ? log.meta.total.toLocaleString() + ' ج' : log.meta.total}</b>`);

                    }

                    if (log.meta.balance !== undefined) {

                        pills.push(`رصيد المحفظة: <b class="text-amber-400 font-bold">${log.meta.balance}</b>`);

                    }

                    if (pills.length > 0) {

                        metaHtml = `

                            <div class="flex items-center gap-2 flex-wrap pt-1 font-mono text-[10px] text-slate-300">

                                ${pills.map(p => `<span class="bg-slate-950/80 px-2 py-0.5 rounded border border-slate-800">${p}</span>`).join('')}

                            </div>

                        `;

                    }

                }



                card.innerHTML = `

                    <div class="flex items-center justify-between text-[10px]">

                        <div class="flex items-center gap-1.5">

                            <span class="px-2 py-0.5 rounded-lg border font-bold ${log.badgeColor}">${log.badge}</span>

                            ${log.ticker ? `<span class="bg-slate-800 px-1.5 py-0.5 rounded font-mono font-bold text-white">${log.ticker}</span>` : ''}

                        </div>

                        <div class="flex items-center gap-2 font-mono text-slate-400">

                            <span>${log.displayDate}</span>

                            <span>•</span>

                            <span class="text-slate-300 font-bold">${log.displayTime}</span>

                        </div>

                    </div>



                    <h4 class="text-xs font-bold text-white leading-snug group-hover:text-indigo-300 transition">${log.title}</h4>

                    <p class="text-[11px] text-slate-300 leading-relaxed">${log.description}</p>

                    ${metaHtml}



                    <div class="pt-1.5 border-t border-slate-800/80 flex items-center justify-between text-[10px] text-indigo-400 group-hover:text-indigo-300 font-medium transition">

                        <span class="flex items-center gap-1">

                            <span>🔍</span>

                            <span>انقر لعرض البيان التفصيلي والصورة المرفقة</span>

                        </span>

                        <span class="text-slate-500 group-hover:text-white transition">←</span>

                    </div>

                `;

                container.appendChild(card);

            });

        }



        function exportUserActivityLog() {

            triggerHaptic('medium');

            const logs = getUserActivityLogs();

            if (logs.length === 0) {

                alert('لا توجد حركات مسجلة لتصديرها حالياً.');

                return;

            }



            let csv = "\uFEFFالتاريخ,الوقت,نوع الحركة,العنوان,التفاصيل,الأصل\n";

            logs.forEach(l => {

                const date = `"${l.displayDate || ''}"`;

                const time = `"${l.displayTime || ''}"`;

                const type = `"${l.badge || l.type}"`;

                const title = `"${(l.title || '').replace(/"/g, '""')}"`;

                const desc = `"${(l.description || '').replace(/"/g, '""')}"`;

                const ticker = `"${l.ticker || ''}"`;

                csv += `${date},${time},${type},${title},${desc},${ticker}\n`;

            });



            const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });

            const url = URL.createObjectURL(blob);

            const a = document.createElement('a');

            a.href = url;

            a.download = `سجل_حركات_المحفظة_${new Date().toISOString().slice(0, 10)}.csv`;

            document.body.appendChild(a);

            a.click();

            document.body.removeChild(a);

            URL.revokeObjectURL(url);

            showToast("✓ تم تصدير سجل حركات المستخدم بنجاح", "success");

        }



        function clearUserActivityLog() {
            triggerHaptic('medium');
            if (confirm("هل أنت متأكد من رغبتك في مسح سجل حركات وتعديلات المحفظة بالكامل؟")) {
                try {
                    localStorage.setItem(ACTIVITY_STORAGE_KEY, JSON.stringify([]));
                    localStorage.setItem('egx_activity_cleared', 'true');
                } catch(e) {}
                renderUserActivityLog('all');
                showToast("✓ تم مسح سجل الحركات بالكامل", "warning");
            }
        }





        



    

